describe('Async Login Spinner Display', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should display spinner while login request is in progress', () => {
    // Intercept the login API call
    cy.intercept('POST', '/api/auth/login', {
      statusCode: 200,
      body: { token: 'abc123', user: { id: 1, name: 'John Doe' } }
    }).as('loginRequest');

    // Verify spinner is visible
    cy.get('[data-testid="spinner"]').should('be.visible');
    cy.get('[data-testid="spinner"]').should('contain', 'Loading...');

    // Click login button
    cy.get('[data-testid="login-button"]').click();

    // Wait for the API call to complete
    cy.wait('@loginRequest');

    // Verify spinner is hidden
    cy.get('[data-testid="spinner"]').should('not.exist');

    // Verify login success message appears
    cy.get('[data-testid="login-success-message"]').should('be.visible');
    cy.get('[data-testid="login-success-message"]').should('contain', 'Login successful');

    // Verify user is redirected to dashboard
    cy.url().should('include', '/dashboard');
  });

  it('should not display spinner when login fails', () => {
    // Intercept the login API call with error response
    cy.intercept('POST', '/api/auth/login', {
      statusCode: 401,
      body: { error: 'Unauthorized' }
    }).as('loginRequest');

    // Click login button
    cy.get('[data-testid="login-button"]').click();

    // Wait for the API call to complete
    cy.wait('@loginRequest');

    // Verify spinner is still visible (should not disappear on error)
    cy.get('[data-testid="spinner"]').should('be.visible');

    // Verify error message is displayed
    cy.get('[data-testid="login-error-message"]').should('be.visible');
    cy.get('[data-testid="login-error-message"]').should('contain', 'Login failed');

    // Verify user is not redirected
    cy.url().should('include', '/login');
  });
});
